head.script:
scwin.onpageload = function() {
    var data = [];
    for (var i = 0; i < 20; i++) {
        for (var j = 0; j < 5; j++) {
            data.push(i + "_" + j);
        }
        data.push("");
    }
    dataList1.setData(data);
    // 감추거나 보여줄 cell의 rowIndex 목록을 위한 임시 dataList
    var data2 = [];
    var rowCnt = dataList1.getRowCount();
    for (var i = 0; i < rowCnt; i++) {
        data2.push(i);
        data2.push(i);
    }
    dataList2.setData(data2);
    scwin.refreshCellVisible();
};
scwin.onpageunload = function() {};
scwin.refreshCellVisible = function() {
    var rowCnt = dataList1.getRowCount();
    for (var i = 0; i < rowCnt; i++) {
        var txt = dataList1.getCellData(i, "column23");
        grd_test1.setCellVisible(i, "column23", txt.trim() != "");
    }
}
scwin.addLine = function(toIndex, startRow, info) {
    var addJSON = dataList1.getRowJSON(startRow);
    dataList1.setRowJSON(toIndex, addJSON);
    if (startRow < toIndex) {
        dataList1.removeRow(startRow);
    } else {
        dataList1.removeRow(startRow + 1);
    }
    scwin.refreshCellVisible();
};
scwin.drag_start = function(row, xml, info) {
    return row;
};
scwin.grd_test1_ondatadrop = function(info) {};
scwin.trigger1_onclick = function(e) {
    var visibleRowArr = checkcombobox1.getValueArray();
    for (var i = 0; i < visibleRowArr.length; i++) {
        grd_test1.setCellVisible(visibleRowArr[i], "column23", true);
    }
};
scwin.trigger2_onclick = function(e) {
    var hiddenRowArr = checkcombobox1.getValueArray();
    for (var i = 0; i < hiddenRowArr.length; i++) {
        grd_test1.setCellVisible(hiddenRowArr[i], "column23", false);
    }
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grd_test1_cell_0_5').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'checkcombobox1_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_0').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'checkcombobox1_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grd_test1_cell_0_5').style.display == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
